import * as THREE from 'three';
import {createExerciseCycle} from './exercise-cycle.js';
import {createTreadmillModel} from './treadmill-model.js';
import {createGymSession,fitGymCamera} from './session.js';
export const GYM_BODY=`<div class="gym-layout"><div class="gym-court" id="gym-court" role="img" aria-label="원래 도름이가 러닝머신 위에서 걷는 모습" tabindex="0"></div><section class="gym-panel" id="gym-panel"><p id="gym-status" role="status"></p><label for="gym-mode">운동 방법 <select id="gym-mode"><option value="easy">편하게 운동 · 자동 걷기</option><option value="standard">직접 속도 맞추기</option></select></label><label class="gym-repeat" for="gym-repeat"><input id="gym-repeat" type="checkbox">5초 쉬었다가 반복</label><div class="gym-actions gym-exercise-actions"><button id="gym-start">걷기 시작</button><button id="gym-pause">잠깐 멈추기</button><button id="gym-stop">운동 멈추기</button><button id="gym-exit">멈추고 내려오기</button></div><label for="gym-pace">목표 걸음 <input id="gym-pace" type="range" min="0.45" max="1.05" step="0.05" value="0.70"></label><div id="gym-practice-controls"><label for="gym-effort">내 걸음 <input id="gym-effort" type="range" min="0.25" max="1.25" step="0.025" value="0.70"></label><div class="gym-hold"><button id="gym-slower">느리게 누르기</button><button id="gym-faster">빠르게 누르기</button></div></div><p id="gym-score" role="status"></p><details id="gym-help"><summary>안내 보기</summary><p>편하게 운동은 30초 동안 선택한 빠르기로 걸어요. 반복을 고르면 벨트를 멈추고 두 발을 딛은 뒤 5초 쉬고 다시 걸어요. 반복은 처음에는 꺼져 있어요.</p><p>운동 멈추기는 다음 반복을 취소하고 벨트를 천천히 멈춰요. 잠깐 멈추기나 화면을 떠나기도 반복을 취소해요. 계속하기는 현재 운동만 이어가요. 내려오기를 누르면 벨트를 멈추고 뒤로 내려와요.</p><p>직접 연습에서는 조절 막대나 ← → 길게 누르기로 속도를 골라요. 안내를 접어도 운동은 계속돼요. 보상이나 저장되는 연속 기록은 없어요.</p><p>탁구 · 배드민턴은 다음에 준비할 운동이에요.</p></details></section></div>`;
export function createGymController({ui,getView,getActors,stage,isAllowed=()=>true,onChange=()=>{},clearInput=()=>{},reduced=false,doc=globalThis.document,win=globalThis.window,sessionFactory=createGymSession,modelFactory=createTreadmillModel,fitCamera=fitGymCamera}){
 const camera=new THREE.OrthographicCamera();const $=id=>doc.querySelector('#'+id);let live=null,pending=false,generation=0;
 const state=s=>s.phase??s.state;
 function listen(n,t,fn,options){if(!n)return;const token=generation,guarded=e=>{if(token===generation&&live)fn(e);};n.addEventListener(t,guarded,options);live.listeners.push([n,t,guarded,options]);}
 function clear(){clearInput();if(!live)return;live.keys.clear();live.pointers.clear();live.model.setInput({slower:false,faster:false});}
 function input(){if(!live)return;const all=[...live.keys.values(),...live.pointers.values()];live.model.setInput({slower:all.includes('slower'),faster:all.includes('faster')});}
 function render(){if(!live)return;const s={...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused},phase=live.session.phase,cycle=live.cycle.snapshot(),ready=phase==='ready'&&['idle','ready','stopped'].includes(state(s));
  $('gym-status').textContent=s.paused?'멈췄어요. 계속하기는 현재 운동만 이어가요':live.exiting?'벨트를 멈추고 뒤로 천천히 내려와요':phase.startsWith('boarding')?'벨트가 멈춰 있어요. 뒤쪽 발판으로 올라가요':phase==='settling'?'벨트가 멈췄어요. 두 발을 편하게 딛어요':cycle.phase==='rest'?`두 발을 딛고 쉬어요 · ${Math.ceil(cycle.remaining)}초 뒤 자동으로 걸어요`:ready?'준비됐어요. 시작은 직접 골라요':state(s)==='stopping'?'벨트를 천천히 멈추고 있어요':`목표 ${s.targetSpeed.toFixed(2)} · 남은 ${Math.ceil(s.remaining)}초`;
  $('gym-start').disabled=!ready||live.exiting||s.paused||cycle.phase==='rest';$('gym-start').textContent=state(s)==='stopped'?'한 번 더 걷기':'걷기 시작';$('gym-pause').disabled=live.exiting&&!s.paused;$('gym-pause').textContent=s.paused?'계속하기':'잠깐 멈추기';$('gym-stop').disabled=live.exiting||s.paused||(!cycle.enabled&&!['start','active'].includes(state(s)));$('gym-exit').disabled=live.exiting;
  $('gym-repeat').checked=cycle.enabled;$('gym-repeat').disabled=live.exiting||s.paused||$('gym-mode').value!=='easy';$('gym-score').hidden=s.mode==='easy';$('gym-practice-controls').hidden=$('gym-mode').value==='easy';$('gym-score').textContent=`일정한 걸음 ${Math.round(s.paceScore??s.paceMatch*100)}% · 안정 ${Math.round(s.stabilityScore??s.stability*100)}%`;
  for(const id of['gym-mode','gym-pace'])$(id).disabled=!ready||live.exiting||s.paused;for(const id of['gym-effort','gym-slower','gym-faster'])$(id).disabled=live.exiting||s.paused||s.mode==='easy'||!['start','active'].includes(state(s));$('gym-effort').value=String(s.effortSpeed);
 }
 function clean({restore}={}){pending=false;if(!live)return;const old=live;live=null;generation++;old.observer?.disconnect();for(const[n,t,fn,o]of old.listeners)n.removeEventListener(t,fn,o);old.cycle.dispose();old.model.dispose?.();old.session.dispose({restore:restore??(getView()===old.source)});stage.classList.remove('gym-open');doc.body?.classList.remove('gym-open');clearInput();onChange();}
 function cancel(){if(!live){pending=false;generation++;return;}clean();ui.close();}
 function close(){if(!live||live.exiting)return;clear();live.cycle.cancel();live.exiting=true;live.suspended=false;live.model.resume();live.model.stop('exit');live.session.requestExit();render();}
 function pause(){if(!live)return;clear();live.cycle.cancel();live.suspended=true;live.model.pause();render();}
 function open(){if(live||pending||!isAllowed())return false;const source=getView(),token=++generation;if(!source?.schoolView?.gymView)return false;if(source.residents?.treadmillOccupied?.()){source.residents.requestTreadmillYield?.();ui.toast('거북이가 러닝머신에서 내려올게요. 뒤쪽 발판에서 잠깐 비켜 주세요');return false;}pending=true;const accepted=ui.workshop('러닝머신 · 편하게 운동',GYM_BODY,()=>{if(token!==generation||!pending)return;if(getView()!==source){pending=false;return;}pending=false;let session;try{session=sessionFactory({view:source,...getActors()});const model=modelFactory({targetSpeed:.7,mode:'easy'});live={session,model,cycle:createExerciseCycle(),source,listeners:[],keys:new Map(),pointers:new Map(),fit:null,exiting:false,suspended:false};stage.classList.add('gym-open');doc.body?.classList.add('gym-open');clearInput();onChange();
   const act=(id,fn)=>listen($(id),'click',e=>{if(token!==generation||!live||$(id).disabled)return;if(e.detail>0&&live.cancelledPointer)return;e.preventDefault();fn();});
   act('gym-start',()=>{clear();if(!live.session.ready)return;const settings={targetSpeed:Number($('gym-pace').value),mode:$('gym-mode').value};live.model.continueSet(settings);live.cycle.start();render();});act('gym-stop',()=>{clear();live.cycle.cancel();live.model.stop();render();});act('gym-exit',close);act('gym-pause',()=>{if(doc.hidden)return;if(live.suspended||live.model.snapshot().paused){clear();live.suspended=false;live.model.resume();render();}else pause();});
   listen($('gym-repeat'),'input',()=>{if(token!==generation||!live||$('gym-repeat').disabled)return;live.cycle.setEnabled($('gym-repeat').checked);if(live.cycle.snapshot().enabled&&['start','active'].includes(state(live.model.snapshot())))live.cycle.start();render();});
   for(const id of['gym-mode','gym-pace','gym-effort'])listen($(id),'input',()=>{if(token!==generation||!live||$(id).disabled)return;clear();if(id==='gym-mode')live.cycle.cancel();if(id==='gym-mode')live.model.setMode($(id).value);else if(id==='gym-pace')live.model.setTargetSpeed(Number($(id).value));else live.model.setInput({effortSpeed:Number($(id).value)});render();});
   for(const direction of['slower','faster']){const node=$('gym-'+direction);listen(node,'pointerdown',e=>{if(node.disabled||e.button!==0||e.isPrimary===false)return;e.preventDefault();live.cancelledPointer=false;node.setPointerCapture?.(e.pointerId);live.pointers.set(e.pointerId,direction);input();});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(node,type,e=>{if(!live)return;if(type!=='pointerup')live.cancelledPointer=true;live.pointers.delete(e.pointerId);input();});listen(node,'click',e=>{if(e.detail!==0||node.disabled)return;const s=live.model.snapshot();live.model.setInput({effortSpeed:s.effortSpeed+(direction==='faster'?.05:-.05)});render();});}
   listen(doc,'keydown',e=>{if(!live||e.ctrlKey||e.metaKey||e.altKey||e.repeat||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const direction=e.code==='ArrowLeft'?'slower':e.code==='ArrowRight'?'faster':null;if(direction&&!$('gym-'+direction).disabled){e.preventDefault();live.keys.set(e.code,direction);input();}});listen(doc,'keyup',e=>{if(live){live.keys.delete(e.code);input();}});
   listen($('gym-panel'),'pointerdown',()=>{if(live)live.cancelledPointer=false;},true);listen($('gym-panel'),'pointercancel',()=>{if(live)live.cancelledPointer=true;},true);
   const modal=$('modal'),exit=modal?.querySelector?.('[data-close]');if(exit)exit.onclick=e=>{if(token!==generation||!live)return;e.preventDefault();close();};listen(modal,'cancel',e=>{e.preventDefault();close();});listen(modal,'click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation?.();}},true);
   listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(win,'pagehide',cancel);const resize=()=>{if(live)viewport(stage.clientWidth,stage.clientHeight);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('gym-court'));}render();resize();$('gym-court').focus();return()=>{if(token===generation)clean();};
  }catch(e){if(live)clean();else session?.dispose();ui.close();ui.toast('러닝머신 뒤쪽에 빈자리가 필요해요. 잠깐 뒤 다시 해 주세요');return;}},{kind:'gym-workshop',closeLabel:'내려오기'});if(!accepted&&token===generation)pending=false;return accepted;}
 function runtimeFailure(){const restore=!!live&&getView()===live.source;clean({restore});ui.close();ui.toast('걷기를 멈췄어요. 잠깐 뒤 다시 해 주세요');}
 function tick(dt){if(!live)return;if(getView()!==live.source){clean({restore:false});ui.close();return;}if(doc.hidden){if(!live.suspended)pause();return;}try{const s=live.model.snapshot();if(!s.paused&&!live.suspended){live.model.update(dt);live.session.tick(dt,live.model.snapshot());if(live.session.ready&&state(live.model.snapshot())==='idle')live.model.ready();if(live.cycle.update(dt,live.model.snapshot(),live.session.ready)&&!live.exiting)live.model.continueSet({targetSpeed:Number($('gym-pace').value),mode:$('gym-mode').value});if(!live.session.done)live.source.schoolView.gymView.setBelt(live.model.snapshot().beltDistance,{reduced});}if(live.session.done){clean();ui.close();return;}render();}catch(error){runtimeFailure();}}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('gym-court').getBoundingClientRect(),base=stage.getBoundingClientRect(),rect={x:Math.max(0,b.left-base.left),y:Math.max(0,b.top-base.top),width:Math.max(1,Math.min(b.width,width)),height:Math.max(1,Math.min(b.height,height))},key=Object.values(rect).join(',');if(live.fit!==key){try{fitCamera(camera,live.session.root,rect);live.fit=key;}catch(error){runtimeFailure();}}return rect;}
 return{open,close,cancel,dispose:cancel,pause,tick,camera,viewport,get active(){return !!live;},snapshot:()=>live?{...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused,cycle:live.cycle.snapshot(),session:live.session.snapshot(),exiting:live.exiting}:null};
}
